@jitclass([("agent_states", int64[:]),
           ("size_state_space", int64[:]),
           ("h_matrix", float64[:,:,:]),
           ("g_matrix", float64[:,:,:]),
           ("h_0", float64[:,:,:]),
           ("prefactor_1", float64[:]),
           ("prefactor_2", float64[:]),
           ("last_upd_G", float64[:,:,:]),
           ("N_upd_H", int64[:]),
           ("N_upd_G", int64[:]),
           ("state_space_factors", float64[:])
          ])
class Foragers_efficient():
    num_agents : int
    num_actions : int
    gamma_damping : float
    eta_glow_damping : float
    policy_type : str
    beta_softmax : float
    num_percepts : int
    agent_states: np.ndarray
    size_state_space: np.ndarray
    initial_h_0: bool
    h_matrix: np.ndarray
    g_matrix: np.ndarray
    h_0: np.ndarray
    g_update : str
    state_space_factors : np.ndarray
    # Efficient H update
    prefactor_1: np.ndarray
    prefactor_2: np.ndarray
    max_no_H_update : int
    N_upd_H : np.ndarray
    # Efficient G update
    last_upd_G: np.ndarray
    N_upd_G: np.ndarray

    def __init__(self,
                 # Number of agents
                 num_agents : int,
                 # Number of actions the agent can take
                 num_actions : int,
                 # Size of the state space, given as an array where each entry is the dimension of each environmental feature
                 size_state_space : np.ndarray,
                 # Gamma damping from PS
                 gamma_damping=0.0,
                 # Eta damping from PS
                 eta_glow_damping=0.0,
                 # Policy type. Can be 'standard' or 'softmax'
                 policy_type='standard',
                 # Beta parameter for softmax policy
                 beta_softmax=3,
                 # If to consider initial probability distribution for the H matrix or not.
                 initial_h_0=False,
                 # value of initial h_matrix
                 h_0=np.array([[[],[],[]]]),
                 # Type of update for the G matrix. Can be 's' (sum) or 'r' (reset)
                 g_update='s',
                 # Max number of steps without updating the H matrix
                 max_no_H_update=int(1e4),
                ):
        """
        Efficient version of Foragers. Uses lazy H-matrix and G-matrix updates
        (only on reward or when max_no_H_update is reached), following the same
        strategy as the single-agent Forager class.

        Key differences vs Foragers:
          - H-matrix is NOT updated every step. Instead, prefactors are used to
            compute the virtually-updated H column on the fly in deliberate().
          - G-matrix updates are lazy: only the (agent, action, percept) entry
            touched during deliberate() is updated; the rest are deferred.
          - _learn_post_reward(rewards) replaces learn(rewards). It flushes the
            pending G-matrix decays and applies the accumulated H-matrix damping
            for each agent that received a reward (or hit max_no_H_update).
        """
        self.num_agents = num_agents
        self.agent_states = np.zeros(num_agents, dtype=np.int64)

        self.num_actions = num_actions
        self.size_state_space = size_state_space
        self.num_percepts = int(np.prod(self.size_state_space))

        # precompute factors for percept_preprocess
        self.state_space_factors = np.zeros(len(self.size_state_space), dtype=np.float64)
        self.state_space_factors[0] = 1
        self.state_space_factors[1:] = np.ascontiguousarray(np.cumprod(self.size_state_space[:-1]))

        self.gamma_damping = gamma_damping
        self.eta_glow_damping = eta_glow_damping
        self.policy_type = policy_type
        self.beta_softmax = beta_softmax
        self.g_update = g_update

        self.initial_h_0 = initial_h_0
        self.h_0 = h_0

        self.init_matrices()

        # Efficient H update prefactors (same as Forager)
        self.max_no_H_update = max_no_H_update
        self.N_upd_H = np.zeros(num_agents, dtype=np.int64)
        self.prefactor_1 = (1 - self.gamma_damping) ** np.arange(1, self.max_no_H_update + 1)
        self.prefactor_2 = np.zeros(self.max_no_H_update)
        for i in range(max_no_H_update):
            self.prefactor_2[i] = self.gamma_damping * np.sum(
                (1 - self.gamma_damping) ** np.arange(i + 1)
            )

        # Efficient G update tracking (per-agent)
        self.N_upd_G = np.zeros(num_agents, dtype=np.int64)
        self.last_upd_G = np.zeros((num_agents, self.num_actions, self.num_percepts))

    def init_matrices(self):
        self.g_matrix = np.zeros((self.num_agents, self.num_actions, self.num_percepts), dtype=np.float64)
        if self.initial_h_0:
            self.h_matrix = self.h_0.copy()
        else:
            self.h_matrix = np.ones((self.num_agents, self.num_actions, self.num_percepts), dtype=np.float64)

    def reset_g(self):
        """Resets g_matrix and all update counters (H and G)."""
        self.g_matrix = np.zeros((self.num_agents, self.num_actions, self.num_percepts), dtype=np.float64)
        self.N_upd_H = np.zeros(self.num_agents, dtype=np.int64)
        self.N_upd_G = np.zeros(self.num_agents, dtype=np.int64)
        self.last_upd_G = np.zeros((self.num_agents, self.num_actions, self.num_percepts))

    def increment_counters(self):
        """Increment N_upd_H and N_upd_G for all agents. Call at start of each timestep."""
        for i in range(self.num_agents):
            self.N_upd_H[i] += 1
            self.N_upd_G[i] += 1

    # ── Efficient G-matrix updates ────────────────────────────────────────

    def _G_upd_single_percept(self, agent_idx, percept, action):
        """Lazily update G for a single (agent, action, percept) tuple."""
        if self.g_update == 's':
            decay = (1 - self.eta_glow_damping) ** (
                self.N_upd_G[agent_idx] - self.last_upd_G[agent_idx, action, percept]
            )
            self.g_matrix[agent_idx, action, percept] = (
                decay * self.g_matrix[agent_idx, action, percept] + 1
            )
        elif self.g_update == 'r':
            self.g_matrix[agent_idx, action, percept] = 1
        self.last_upd_G[agent_idx, action, percept] = self.N_upd_G[agent_idx]

    def _G_upd_full(self, agent_idx):
        """Apply all pending G-matrix decays for one agent, then reset its counters."""
        n = self.N_upd_G[agent_idx]
        for a in range(self.num_actions):
            for p in range(self.num_percepts):
                self.g_matrix[agent_idx, a, p] *= (
                    (1 - self.eta_glow_damping) ** (n - self.last_upd_G[agent_idx, a, p])
                )
                self.last_upd_G[agent_idx, a, p] = 0.0
        self.N_upd_G[agent_idx] = 0

    # ── Efficient H-matrix updates ────────────────────────────────────────

    def _H_upd_single_percept(self, agent_idx, t, percept):
        """Return the virtually-updated h_matrix column for one agent/percept
        without modifying h_matrix."""
        if self.initial_h_0:
            return (self.prefactor_1[t - 1] * self.h_matrix[agent_idx, :, percept]
                    + self.prefactor_2[t - 1] * self.h_0[agent_idx, :, percept])
        else:
            return (self.prefactor_1[t - 1] * self.h_matrix[agent_idx, :, percept]
                    + self.prefactor_2[t - 1])

    def _learn_post_reward(self, rewards):
        """Update H (and flush G) for each agent that received a reward or hit max_no_H_update.
        
        Parameters
        ----------
        rewards : array of floats, shape (num_agents,)
        """
        for i in range(self.num_agents):
            if rewards[i] > 0 or self.N_upd_H[i] >= self.max_no_H_update - 1:
                if self.N_upd_H[i] == 0:
                    continue
                self._G_upd_full(i)
                if self.initial_h_0:
                    self.h_matrix[i] = (
                        self.prefactor_1[self.N_upd_H[i] - 1] * self.h_matrix[i]
                        + self.prefactor_2[self.N_upd_H[i] - 1] * self.h_0[i]
                        + rewards[i] * self.g_matrix[i]
                    )
                else:
                    self.h_matrix[i] = (
                        self.prefactor_1[self.N_upd_H[i] - 1] * self.h_matrix[i]
                        + self.prefactor_2[self.N_upd_H[i] - 1]
                        + rewards[i] * self.g_matrix[i]
                    )
                self.N_upd_H[i] = 0

    # ── Percept preprocessing ─────────────────────────────────────────────

    def percept_preprocess(self, observations):
        """Same as Foragers.percept_preprocess."""
        
        percepts = np.dot(observations, np.ascontiguousarray(self.state_space_factors))
        return percepts.astype(np.int64)

    # ── Deliberation ──────────────────────────────────────────────────────

    def deliberate(self, observations):
        """
        Like Foragers.deliberate but uses efficient H lookup and lazy G update.
        """
        percepts = self.percept_preprocess(observations)

        probs = np.zeros((self.num_agents, self.num_actions), dtype=np.float64)

        if self.policy_type == 'standard':
            for i in range(self.num_agents):
                if self.N_upd_H[i] == 0:
                    h_vector = self.h_matrix[i, :, percepts[i]]
                else:
                    h_vector = self._H_upd_single_percept(i, self.N_upd_H[i], percepts[i])
                probs[i, :] = h_vector / np.sum(h_vector)
        elif self.policy_type == 'softmax':
            for i in range(self.num_agents):
                if self.N_upd_H[i] == 0:
                    h_vector = self.beta_softmax * self.h_matrix[i, :, percepts[i]]
                else:
                    h_vector = self.beta_softmax * self._H_upd_single_percept(
                        i, self.N_upd_H[i], percepts[i]
                    )
                h_vector_mod = h_vector - np.max(h_vector)
                probs[i, :] = np.exp(h_vector_mod) / np.sum(np.exp(h_vector_mod))

        actions = rand_choice_vectorized(probs=probs)

        for i in range(self.num_agents):
            self._G_upd_single_percept(i, percepts[i], actions[i])

        return actions

    def probability_distr(self, percepts):
        """Like Foragers.probability_distr but uses efficient H lookup."""
        probs = np.zeros((self.num_agents, self.num_actions), dtype=np.float64)

        if self.policy_type == 'standard':
            for i in range(self.num_agents):
                if self.N_upd_H[i] == 0:
                    h_vector = self.h_matrix[i, :, percepts[i]]
                else:
                    h_vector = self._H_upd_single_percept(i, self.N_upd_H[i], percepts[i])
                probs[i, :] = h_vector / np.sum(h_vector)
        elif self.policy_type == 'softmax':
            for i in range(self.num_agents):
                if self.N_upd_H[i] == 0:
                    h_vector = self.beta_softmax * self.h_matrix[i, :, percepts[i]]
                else:
                    h_vector = self.beta_softmax * self._H_upd_single_percept(
                        i, self.N_upd_H[i], percepts[i]
                    )
                h_vector_mod = h_vector - np.max(h_vector)
                probs[i, :] = np.exp(h_vector_mod) / np.sum(np.exp(h_vector_mod))

        return probs

    # ── Action & state ────────────────────────────────────────────────────

    def act(self, actions):
        """Same as Foragers.act."""
        self.agent_states[actions == 1] = 0
        self.agent_states[actions == 0] += 1

    def get_state(self):
        """Same as Foragers.get_state."""
        return self.agent_states

