@njit(parallel=True)
def _run_collect_dict_ind_numba(episodes, time_ep,
                                Nt, L, r, tau, tau_reward,
                                num_agents, agent_step,
                                visual_range, visual_angle,
                                shared_depletion, visual_activated,
                                num_actions, state_space,
                                gamma_damping, eta_glow_damping,
                                is_learning_cases,
                                initial_h_0, h_0, g_update,
                                policy_type, beta_softmax, max_no_H_update,
                                upd_pos_method, turn_angle,
                                n_run, ablation):
    """Numba core for run_collect_dict_ind.

    Expects is_learning_cases as a 2-D bool array with shape (n_cases, num_agents).
    """
    n_Nt = len(Nt)
    n_L = len(L)
    n_r = len(r)
    n_tau = len(tau)
    n_tau_reward = len(tau_reward)
    n_gamma = len(gamma_damping)
    n_eta = len(eta_glow_damping)
    n_turn = len(turn_angle)
    n_VR = len(visual_range)
    n_learn = is_learning_cases.shape[0]

    total_combos = n_Nt * n_L * n_r * n_tau * n_tau_reward * n_gamma * n_eta * n_turn * n_VR * n_learn
    total_iters = total_combos * n_run

    save_h_matrix = np.zeros((n_run, total_combos, num_agents, num_actions, state_space.prod()))
    save_rewards = np.zeros((n_run, total_combos, num_agents, episodes))

    # cumulative strides for combo index decomposition
    stride_L = n_Nt
    stride_r = stride_L * n_L
    stride_tau = stride_r * n_r
    stride_tr = stride_tau * n_tau
    stride_gam = stride_tr * n_tau_reward
    stride_eta = stride_gam * n_gamma
    stride_turn = stride_eta * n_eta
    stride_VR = stride_turn * n_turn
    stride_learn = stride_VR * n_VR

    for flat_idx in prange(total_iters):
        run_idx = flat_idx // total_combos
        combo_idx = flat_idx % total_combos

        i_Nt = (combo_idx // 1) % n_Nt
        i_L = (combo_idx // stride_L) % n_L
        i_r = (combo_idx // stride_r) % n_r
        i_tau = (combo_idx // stride_tau) % n_tau
        i_tau_reward = (combo_idx // stride_tr) % n_tau_reward
        i_gamma = (combo_idx // stride_gam) % n_gamma
        i_eta = (combo_idx // stride_eta) % n_eta
        i_turn = (combo_idx // stride_turn) % n_turn
        i_VR = (combo_idx // stride_VR) % n_VR
        i_learn = (combo_idx // stride_learn) % n_learn

        gamma_vec = np.full(num_agents, gamma_damping[i_gamma])
        eta_vec = np.full(num_agents, eta_glow_damping[i_eta])

        is_learning_case = np.empty(num_agents, dtype=np.bool_)
        for i in range(num_agents):
            is_learning_case[i] = is_learning_cases[i_learn, i]

        agents = Foragers_efficient_ind(
            num_agents, num_actions, state_space,
            gamma_vec, eta_vec, is_learning_case,
            policy_type, beta_softmax,
            initial_h_0, h_0, g_update, max_no_H_update,
        )

        env = CollectiveEnv(
            num_agents, Nt[i_Nt], L[i_L], r[i_r], tau[i_tau], agent_step,
            visual_range[i_VR], visual_angle, shared_depletion,
            tau_reward[i_tau_reward], upd_pos_method, turn_angle[i_turn]
        )

        rews, mat = train_loop_collective(
            episodes, time_ep, env, agents, state_space[0],
            visual_activated, upd_pos_method, ablation
        )

        for t in range(episodes):
            save_rewards[run_idx, combo_idx, :, t] = rews[:, t]
        save_h_matrix[run_idx, combo_idx] = mat

    return save_rewards, save_h_matrix


def run_collect_dict_ind(episodes, time_ep,
                         Nt=np.array([100]),
                         L=np.array([100.0]),
                         r=np.array([0.5]),
                         tau=np.array([5]),
                         tau_reward=np.array([1]),
                         num_agents=10,
                         agent_step=1,
                         visual_range=np.array([2.0]),
                         visual_angle=np.pi / 2,
                         shared_depletion=True,
                         visual_activated=True,
                         num_actions=2,
                         state_space=np.array([50, 2, 2]),
                         gamma_damping=np.array([0.00001]),
                         eta_glow_damping=np.array([0.1]),
                         is_learning=np.array([[True]]),
                         initial_h_0=False,
                         h_0=np.zeros((1, 2, 200)),
                         g_update='s',
                         policy_type='standard',
                         beta_softmax=3,
                         max_no_H_update=int(1e3),
                         upd_pos_method='RND',
                         turn_angle=np.array([np.pi / 4]),
                         n_run=1,
                         ablation=None):
    """
    Same parameter sweep as run_collective_dict, with an extra sweep over
    per-agent learning masks for Foragers_efficient_ind.

    is_learning supports:
    - shape (num_agents,) -> treated as a single case
    - shape (n_cases, num_agents) -> one case per row
    - list/list-of-lists equivalents of the above
    """
    Nt = np.asarray(Nt)
    L = np.asarray(L)
    r = np.asarray(r)
    tau = np.asarray(tau)
    tau_reward = np.asarray(tau_reward)
    visual_range = np.asarray(visual_range)
    gamma_damping = np.asarray(gamma_damping)
    eta_glow_damping = np.asarray(eta_glow_damping)
    turn_angle = np.asarray(turn_angle)

    learn_arr = np.asarray(is_learning, dtype=np.bool_)
    if learn_arr.ndim == 1:
        learn_cases = learn_arr.reshape(1, learn_arr.shape[0])
    elif learn_arr.ndim == 2:
        learn_cases = learn_arr
    else:
        raise ValueError("is_learning must be a 1D or 2D boolean array (or list/list-of-lists).")

    if learn_cases.shape[1] != num_agents:
        raise ValueError("Each is_learning case must have length num_agents.")

    return _run_collect_dict_ind_numba(
        episodes, time_ep,
        Nt, L, r, tau, tau_reward,
        num_agents, agent_step,
        visual_range, visual_angle,
        shared_depletion, visual_activated,
        num_actions, state_space,
        gamma_damping, eta_glow_damping,
        learn_cases,
        initial_h_0, h_0, g_update,
        policy_type, beta_softmax, max_no_H_update,
        upd_pos_method, turn_angle,
        n_run, ablation
    )

